        "Math / Quantitative": 68, "Language Understanding": 80, "Multimodal Understanding": 72,
        "Instruction Following": 82, "Inference Speed": 78, "Knowledge Recall": 79,
        "top": False
    },
    {
        "model": "Claude 3.5 Sonnet", "family": "Claude", "Reasoning": 94, "Code Generation": 93,
        "Math / Quantitative": 82, "Language Understanding": 93, "Multimodal Understanding": 85,
        "Instruction Following": 95, "Inference Speed": 38, "Knowledge Recall": 90,
        "top": True
    },
    {
        "model": "Claude 3 Haiku", "family": "Claude", "Reasoning": 68, "Code Generation": 70,
        "Math / Quantitative": 60, "Language Understanding": 76, "Multimodal Understanding": 65,
