        "top": True
    },
    {
        "model": "Gemini 1.5 Flash", "family": "Gemini", "Reasoning": 70, "Code Generation": 68,
        "Math / Quantitative": 58, "Language Understanding": 75, "Multimodal Understanding": 82,
        "Instruction Following": 74, "Inference Speed": 88, "Knowledge Recall": 74,
        "top": False
    },
    {
        "model": "LLaMA 3.1 405B", "family": "LLaMA", "Reasoning": 86, "Code Generation": 84,
        "Math / Quantitative": 90, "Language Understanding": 84, "Multimodal Understanding": 45,
        "Instruction Following": 80, "Inference Speed": 35, "Knowledge Recall": 88,
        "top": True
    },
    {
        "model": "LLaMA 3.1 70B", "family": "LLaMA", "Reasoning": 76, "Code Generation": 74,
        "Math / Quantitative": 78, "Language Understanding": 75, "Multimodal Understanding": 40,
        "Instruction Following": 72, "Inference Speed": 62, "Knowledge Recall": 76,
        "top": False
    },
    {
        "model": "Qwen2.5 72B", "family": "Qwen", "Reasoning": 83, "Code Generation": 86,
        "Math / Quantitative": 92, "Language Understanding": 82, "Multimodal Understanding": 52,
        "Instruction Following": 81, "Inference Speed": 48, "Knowledge Recall": 85,
        "top": True
    },
    {
        "model": "Qwen2.5 7B", "family": "Qwen", "Reasoning": 58, "Code Generation": 62,
        "Math / Quantitative": 70, "Language Understanding": 64, "Multimodal Understanding": 38,
        "Instruction Following": 60, "Inference Speed": 93, "Knowledge Recall": 60,
        "top": False
    }
]

dimensions = [
    "Reasoning", "Inference Speed", 
    "Multimodal Understanding", "Math / Quantitative",
    "Code Generation", "Language Understanding", 
    "Instruction Following", "Knowledge Recall"
]

colors = {
    "GPT": "#2563eb",
    "Claude": "#7c3aed",
    "Gemini": "#059669",
    "LLaMA": "#d97706",
    "Qwen": "#e11d48"
}

width, height = 1400, 700
margin = {"top": 60, "bottom": 40, "left": 60, "right": 220}
inner_width = width - margin["left"] - margin["right"]
inner_height = height - margin["top"] - margin["bottom"]

x_scale = {d: i * (inner_width / (len(dimensions) - 1)) for i, d in enumerate(dimensions)}
def y_scale(val):
    return inner_height - ((val - 20) / 80) * inner_height

svg_content = f'<svg viewBox="0 0 {width} {height}" style="width: 100%; height: auto; font-family: Inter, sans-serif; overflow: visible;">'

# Grid lines & Axes
for d in dimensions:
    x = x_scale[d]
    svg_content += f'<line x1="{x + margin["left"]}" y1="{margin["top"]}" x2="{x + margin["left"]}" y2="{margin["top"] + inner_height}" stroke="var(--border)" stroke-width="1.5" stroke-dasharray="4,4"/>'
    # Axis Title
    parts = d.split(" ")
    if len(parts) > 1 and len(d) > 15:
        # Multiline
        svg_content += f'<text x="{x + margin["left"]}" y="{margin["top"] - 30}" fill="var(--text)" text-anchor="middle" font-size="14" font-weight="600">{parts[0]} {parts[1]}</text>'
        svg_content += f'<text x="{x + margin["left"]}" y="{margin["top"] - 14}" fill="var(--text)" text-anchor="middle" font-size="14" font-weight="600">{" ".join(parts[2:])}</text>'
    else:
        svg_content += f'<text x="{x + margin["left"]}" y="{margin["top"] - 14}" fill="var(--text)" text-anchor="middle" font-size="15" font-weight="600">{d}</text>'

    # Tick marks (100, 80, 60, 40)
    for tick in [20, 40, 60, 80, 100]:
        ty = y_scale(tick) + margin["top"]
        if d == dimensions[0]:
            svg_content += f'<text x="{x + margin["left"] - 10}" y="{ty + 4}" fill="var(--text-secondary)" text-anchor="end" font-size="13">{tick}</text>'
        svg_content += f'<line x1="{x + margin["left"] - 4}" y1="{ty}" x2="{x + margin["left"] + 4}" y2="{ty}" stroke="var(--border)" stroke-width="1.5"/>'

# Draw lines
for row in sorted(data, key=lambda x: (x["family"], 1 if x["top"] else 0)):
    points = []
    for d in dimensions:
        points.append(f'{x_scale[d] + margin["left"]},{y_scale(row[d]) + margin["top"]}')
    color = colors[row["family"]]
    stroke_width = 4.5 if row["top"] else 2
    opacity = 0.95 if row["top"] else 0.4
    dash = "" if row["top"] else 'stroke-dasharray="6,4"'

    svg_content += f'<polyline points="{" ".join(points)}" fill="none" stroke="{color}" stroke-width="{stroke_width}" opacity="{opacity}" {dash} stroke-linejoin="round"/>'

    # Circles at points
    for i, d in enumerate(dimensions):
        r = 6 if row["top"] else 3
        svg_content += f'<circle cx="{x_scale[d] + margin["left"]}" cy="{y_scale(row[d]) + margin["top"]}" r="{r}" fill="{color}" opacity="{opacity}"/>'

# Draw right-aligned labels for final dimension
for row in data:
    final_x = x_scale[dimensions[-1]] + margin["left"]
    final_y = y_scale(row[dimensions[-1]]) + margin["top"]
    color = colors[row["family"]]
    opacity = 1.0 if row["top"] else 0.6
    font_weight = 700 if row["top"] else 400
    font_size = 15 if row["top"] else 13

    svg_content += f'<text x="{final_x + 12}" y="{final_y + 4}" fill="{color}" opacity="{opacity}" font-size="{font_size}" font-weight="{font_weight}">{row["model"]}</text>'

# Legend
legend_x = width - 160
legend_y = margin["top"]
svg_content += f'<text x="{legend_x}" y="{legend_y}" fill="var(--text)" font-size="16" font-weight="700">Model Families</text>'
for i, fam in enumerate(colors.keys()):
    ly = legend_y + 30 + i * 30
    svg_content += f'<line x1="{legend_x}" y1="{ly - 4}" x2="{legend_x + 20}" y2="{ly - 4}" stroke="{colors[fam]}" stroke-width="4"/>'
    svg_content += f'<text x="{legend_x + 30}" y="{ly}" fill="var(--text)" font-size="15">{fam}</text>'

svg_content += '</svg>'

html_template = f"""<!DOCTYPE html>
<html lang="en" class="theme-light">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=1600, initial-scale=1.0">
  <title>AI Model Benchmark Parallel Coordinates</title>
  <link href="file:///app/libs/fonts/inter.css" rel="stylesheet">
  <style>
    *, *::before, *::after {{ box-sizing: border-box; margin: 0; padding: 0; }}
    html.theme-light {{
      --bg: #FAFAF9; --surface: #FFFFFF; --surface-hover: #F5F5F4;
      --border: rgba(0,0,0,0.1);
      --text: #0f172a; --text-secondary: #64748b;
      --accent: #2563eb; --accent-secondary: #7c3aed;
      --positive: #059669; --negative: #e11d48; --warning: #d97706;
    }}
    body {{
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
      background: var(--bg); color: var(--text);
      line-height: 1.6; -webkit-font-smoothing: antialiased;
      width: 1600px; height: 1000px; overflow: hidden;
      display: flex; flex-direction: column; padding: 40px;
    }}
    h1 {{ font-size: 2.8rem; font-weight: 700; color: var(--text); letter-spacing: -0.03em; margin-bottom: 8px; }}
    h2 {{ font-size: 1.2rem; font-weight: 400; color: var(--text-secondary); margin-bottom: 40px; }}
    .card {{
      background: var(--surface); border: 1px solid var(--border);
      border-radius: 16px; padding: 32px;
      box-shadow: 0 4px 20px rgba(0,0,0,0.03);
      flex: 1; display: flex; align-items: center; justify-content: center;
    }}
    .insights-grid {{
      display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; margin-top: 32px;
    }}
    .insight-card {{
      background: var(--surface); border: 1px solid var(--border);
      border-radius: 12px; padding: 20px;
    }}
    .insight-title {{ font-weight: 600; font-size: 15px; color: var(--text); margin-bottom: 6px; }}
    .insight-desc {{ font-size: 14px; color: var(--text-secondary); line-height: 1.5; }}
  </style>
</head>
<body>
  <header>
    <h1>AI Model Capability Profiles</h1>
    <h2>Parallel coordinates benchmark across 8 dimensions. Score normalized to 0-100.</h2>
  </header>

  <div class="card">
    {svg_content}
  </div>

  <div class="insights-grid">
    <div class="insight-card">
      <div class="insight-title">Reasoning vs. Speed</div>
      <div class="insight-desc">Models scoring high on Reasoning tend to exhibit sharp drops in Inference Speed, creating a visible "X" crossing pattern.</div>
    </div>
    <div class="insight-card">
      <div class="insight-title">Multimodal vs. Math</div>
      <div class="insight-desc">Divergent trajectories between Multimodal Understanding and Math/Quantitative showcase model specialization trade-offs.</div>
    </div>
    <div class="insight-card">
      <div class="insight-title">Family Clustering</div>
      <div class="insight-desc">Model families cluster across dimensions, exhibiting unique capability signatures regardless of model size.</div>
    </div>
    <div class="insight-card">
      <div class="insight-title">Top Performers</div>
      <div class="insight-desc">Flagship models (bold lines) dominate across multiple axes compared to their lightweight counterparts.</div>
    </div>
  </div>
</body>
</html>
"""

with open('/app/output/result.html', 'w') as f:
    f.write(html_template)
EOF
